"use client";

import * as React from "react";
import { NavigationMenu as NavigationMenuPrimitive } from "@base-ui/react/navigation-menu";
import { cva } from "class-variance-authority";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { focusRing, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished NavigationMenu: a header row of sections whose panels drop into
 * one shared raised umber viewport. The viewport is rendered for you after
 * the list.
 */
function NavigationMenu({
  className,
  children,
  ...props
}: WithClassName<NavigationMenuPrimitive.Root.Props>) {
  return (
    <NavigationMenuPrimitive.Root
      data-slot="navigation-menu"
      className={cn(
        "relative z-10 flex max-w-max flex-1 items-center justify-center",
        className,
      )}
      {...props}
    >
      {children}
      <NavigationMenuViewport />
    </NavigationMenuPrimitive.Root>
  );
}
NavigationMenu.displayName = "NavigationMenu";

/** The row of top-level items, spaced 0.25rem apart. */
function NavigationMenuList({
  className,
  ...props
}: WithClassName<NavigationMenuPrimitive.List.Props>) {
  return (
    <NavigationMenuPrimitive.List
      data-slot="navigation-menu-list"
      className={cn(
        "flex flex-1 list-none items-center justify-center gap-1",
        className,
      )}
      {...props}
    />
  );
}
NavigationMenuList.displayName = "NavigationMenuList";

/** One top-level section: a trigger and its panel, or a single link. */
const NavigationMenuItem = NavigationMenuPrimitive.Item;

/**
 * The top-level item: muted semibold text in a pill. It rises as a graphite
 * bevel while its panel is open, and the current section reads in copper.
 * Apply it to a plain top-level link too, so links and triggers line up.
 */
const navigationMenuTriggerStyle = cva(
  [
    "group inline-flex h-10 w-max select-none items-center justify-center gap-1.5 rounded-full px-4 text-sm font-semibold tracking-[0.016em] text-muted-foreground",
    "transition-[box-shadow,color] duration-fast ease-(--ease-out)",
    "[@media(hover:hover)_and_(pointer:fine)]:hover:text-foreground",
    focusRing,
    "data-[popup-open]:bg-(image:--fill-raised) data-[popup-open]:text-foreground data-[popup-open]:shadow-(--bevel-raised)",
    "data-[active]:text-primary-text",
    "disabled:pointer-events-none disabled:opacity-50",
  ].join(" "),
);

/** A top-level trigger with a caret that turns over while its panel is open. */
function NavigationMenuTrigger({
  className,
  children,
  ...props
}: WithClassName<NavigationMenuPrimitive.Trigger.Props>) {
  return (
    <NavigationMenuPrimitive.Trigger
      data-slot="navigation-menu-trigger"
      className={cn(navigationMenuTriggerStyle(), className)}
      {...props}
    >
      {children}
      <Icon
        icon="ph:caret-down"
        className="size-3.5 text-muted-foreground transition-transform duration-base ease-(--ease-out) group-data-[popup-open]:rotate-180"
        aria-hidden="true"
      />
    </NavigationMenuPrimitive.Trigger>
  );
}
NavigationMenuTrigger.displayName = "NavigationMenuTrigger";

/**
 * One section's panel. Moving between sections slides the new panel in from
 * the side the pointer came from while the old one fades out.
 */
function NavigationMenuContent({
  className,
  ...props
}: WithClassName<NavigationMenuPrimitive.Content.Props>) {
  return (
    <NavigationMenuPrimitive.Content
      data-slot="navigation-menu-content"
      className={cn(
        "w-full p-2 md:absolute md:start-0 md:top-0 md:w-auto",
        "transition-[opacity,translate] duration-base ease-(--ease-out)",
        "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
        "data-[starting-style]:data-[activation-direction=left]:-translate-x-6",
        "data-[starting-style]:data-[activation-direction=right]:translate-x-6",
        "data-[ending-style]:data-[activation-direction=left]:translate-x-6",
        "data-[ending-style]:data-[activation-direction=right]:-translate-x-6",
        className,
      )}
      {...props}
    />
  );
}
NavigationMenuContent.displayName = "NavigationMenuContent";

/**
 * A link inside a panel: a block with a 0.625rem corner that takes the warm
 * accent under the pointer. The current page reads in copper.
 */
function NavigationMenuLink({
  className,
  ...props
}: WithClassName<NavigationMenuPrimitive.Link.Props>) {
  return (
    <NavigationMenuPrimitive.Link
      data-slot="navigation-menu-link"
      className={cn(
        "flex flex-col gap-1 rounded-md p-3 text-sm text-foreground outline-none",
        "transition-colors duration-fast ease-(--ease-out)",
        "[@media(hover:hover)_and_(pointer:fine)]:hover:bg-accent focus-visible:bg-accent",
        "data-[active]:font-semibold data-[active]:text-primary-text",
        className,
      )}
      {...props}
    />
  );
}
NavigationMenuLink.displayName = "NavigationMenuLink";

/**
 * The shared panel window: the raised umber panel. It resizes to fit each
 * section as you move along the row, and grows in when it first opens.
 */
function NavigationMenuViewport({
  className,
  ...props
}: WithClassName<NavigationMenuPrimitive.Viewport.Props>) {
  return (
    <NavigationMenuPrimitive.Portal>
      <NavigationMenuPrimitive.Positioner
        sideOffset={10}
        collisionPadding={16}
        className="isolate z-50"
      >
        <NavigationMenuPrimitive.Popup
          data-slot="navigation-menu-popup"
          className={cn(
            popoverSurface,
            popupMotion,
            "relative h-(--popup-height) w-(--popup-width) max-w-(--available-width) overflow-hidden",
            "transition-[opacity,scale,width,height]",
          )}
        >
          <NavigationMenuPrimitive.Viewport
            data-slot="navigation-menu-viewport"
            className={cn("relative size-full overflow-hidden", className)}
            {...props}
          />
        </NavigationMenuPrimitive.Popup>
      </NavigationMenuPrimitive.Positioner>
    </NavigationMenuPrimitive.Portal>
  );
}
NavigationMenuViewport.displayName = "NavigationMenuViewport";

/**
 * Kept so existing imports still compile. The Base UI navigation menu has no
 * part that tracks the active trigger along the list, so this renders nothing.
 */
function NavigationMenuIndicator(props: React.ComponentPropsWithoutRef<"div">) {
  void props;
  return null;
}
NavigationMenuIndicator.displayName = "NavigationMenuIndicator";

export {
  navigationMenuTriggerStyle,
  NavigationMenu,
  NavigationMenuList,
  NavigationMenuItem,
  NavigationMenuContent,
  NavigationMenuTrigger,
  NavigationMenuLink,
  NavigationMenuIndicator,
  NavigationMenuViewport,
};
